            for rot in range(4):
                transformed = []
                for r, c, v in pts:
                    x, y = r, c * flip
                    for _ in range(rot):
                        x, y = y, -x
                    transformed.append((x, y, v))
                r0 = min(x for x, y, v in transformed)
                c0 = min(y for x, y, v in transformed)
                norm = tuple(sorted((x-r0, y-c0, v)
                                    for x, y, v in transformed))
                found[norm] = norm
        return list(found.values())

    ori = [orientations(pts) for _, pts in pieces]
    marked_idx = next(i for i, (key, _) in enumerate(pieces)
                      if key == "marked")

