                            continue
                    mask = sum(1 << (r*side+c) for r, c, v in placed)
                    opts.append((mask, placed))
        placements.append(opts)

    full = (1 << board_area) - 1
    answer = None

    # Try each orientation of the marked piece fixed at the upper-left,
    # then tile the remaining board with the remaining pieces.
    def search(mask, used, vals):
        nonlocal answer
        if mask == full:
            answer = vals[:]
            return True
        bit = next((1 << k for k in range(board_area)
                    if not (mask >> k) & 1), None)
        if bit is None:
            return False
        for i in range(len(pieces)):
            if used >> i & 1:
