                    if search(mask | pmask, used | (1 << i), vals):
                        return True
                    for r, c, v in placed:
                        vals[r*side+c] = 0
        return False

    search(0, 0, [0] * board_area)
    if answer is None:
        return [[0] * side for _ in range(side)]
